class KV:
    def __init__(self):
        self.d = {}

    def put(self, k, v, now, ttl=None):
        exp = None if ttl is None else now + ttl
        self.d[k] = (v, exp)

    def get(self, k, now):
        if k not in self.d:
            return None
        v, exp = self.d[k]
        if exp is not None and now >= exp:
            return None
        return v

    def keys(self, now):
        out = []
        for k, (v, exp) in self.d.items():
            if exp is None or now < exp:
                out.append(k)
        return sorted(out)

    def delete(self, k):
        self.d.pop(k, None)

