class Tx:
    def __init__(self):
        self.data = {}
        self.active = False
        self.staged = {}

    def begin(self):
        if self.active:
            raise TxError('already active')
        self.active = True
        self.staged = {}

    def put(self, k, v):
        if not self.active:
            raise TxError('no tx')
        self.staged[k] = ('put', v)

    def delete(self, k):
        if not self.active:
            raise TxError('no tx')
        self.staged[k] = ('del', None)

    def get(self, k):
        if k in self.staged:
            op, v = self.staged[k]
            return v if op == 'put' else None
        return self.data.get(k)

    def scan(self):
        keys = set(self.data) | set(self.staged)
        out = []
        for k in sorted(keys):
            if self.get(k) is not None:
                out.append(k)
        return out

    def commit(self):
        if not self.active:
            raise TxError('no tx')
        for k, (op, v) in self.staged.items():
            if op == 'put':
                self.data[k] = v
            else:
                self.data.pop(k, None)
        self.staged = {}
        self.active = False

    def rollback(self):
        if not self.active:
            raise TxError('no tx')
        self.staged = {}
        self.active = False

